    public static void main(String[] args) {
        new Solver();
    }

    static class Solver {
        IO io;

        public Solver() {
            io = new IO();
            try {
                process();
            } catch (RuntimeException e) {
                if (!"Clean exit".equals(e.getMessage())) {
                    throw e;
                }
            } finally {
                io.close();
            }
        }

        void process() {
            long n = io.nextLong();
            long m = io.nextLong();
            if (m < n) {
                long temp = m;
                m = n;
                n = temp;
            }

            if (n == 1) {
                io.println(calculateBrute(m));
                return;
            }
            if (n == 2) {
                if (m < 3) io.println(0);
                else if (m == 3) io.println(4);
                else if (m == 7) io.println(12);
                else io.println(2 * m);
                return;
            }

            io.println(2 * (n * m / 2));
        }

        long calculateBrute(long m) {
            long res = 6 * (m / 6);
            if (m % 6 == 5) res += 4;
            else if (m % 6 == 4) res += 2;
            return res;
        }
    }

    static class IO extends PrintWriter {
        private InputStreamReader inStream;
        private static final int BUFFER_SIZE = 1 << 15;
        private char[] buf;
        private int bufPos;
        private int bufLen;
        private StringBuilder sb;

        public IO() {
            super(new BufferedOutputStream(System.out));
            inStream = new InputStreamReader(System.in);
            buf = new char[BUFFER_SIZE];
            bufPos = 0;
            bufLen = 0;
            sb = new StringBuilder();
        }

        private void fillBuffer() throws IOException {
            bufLen = inStream.read(buf, 0, BUFFER_SIZE);
            bufPos = 0;
        }

        private boolean hasNext() throws IOException {
            if (bufPos >= bufLen) {
                fillBuffer();
            }
            return bufLen > 0;
        }

        private boolean isSpace(char c) {
            return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
        }

        private void skipSpaces() throws IOException {
            while (true) {
                if (!hasNext()) break;
                if (!isSpace(buf[bufPos])) break;
                bufPos++;
            }
        }

        public String next() {
            try {
                sb.setLength(0);
                skipSpaces();
                int startIdx = bufPos;
                while (true) {
                    if (!hasNext()) break;
                    if (isSpace(buf[bufPos])) break;
                    bufPos++;
                }
                sb.append(buf, startIdx, bufPos - startIdx);
                return sb.toString();
            } catch (IOException e) {
                throw new RuntimeException("IO.next: IOException");
            }
        }

        public long nextLong() {
            try {
                long res = 0;
                boolean positive = true;
                skipSpaces();
                if (buf[bufPos] == '-') {
                    positive = false;
                    bufPos++;
                }
                while (true) {
                    if (!hasNext()) break;
                    if (isSpace(buf[bufPos])) break;
                    res = res * 10 + (buf[bufPos] - '0');
                    bufPos++;
                }
                return positive ? res : -res;
            } catch (IOException e) {
                throw new RuntimeException("IO.nextLong: IOException");
            }
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }
